import java.util.*;

class Solution {
    public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        result.add(new ArrayList<>());

        for (int v : nums) {
            List<List<Integer>> next = new ArrayList<>();
            for (List<Integer> p : result) {
                for (int i = 0; i <= p.size(); i++) {
                    List<Integer> q = new ArrayList<>(p);
                    q.add(i, v);
                    next.add(q);
                }
            }
            result = next;
        }
        return result;
    }
}

import java.util.*;

class Solution {
    private List<List<Integer>> result = new ArrayList<>();
    private List<Integer> path = new ArrayList<>();
    private boolean[] used;

    public List<List<Integer>> permute(int[] nums) {
        used = new boolean[nums.length];
        backtrack(nums);
        return result;
    }

    private void backtrack(int[] nums) {
        if (path.size() == nums.length) {
            result.add(new ArrayList<>(path));   // 必须复制
            return;
        }
        for (int i = 0; i < nums.length; i++) {
            if (used[i]) continue;

            used[i] = true;
            path.add(nums[i]);

            backtrack(nums);

            path.remove(path.size() - 1);   // 撤销
            used[i] = false;
        }
    }
}

import java.util.*;

class Solution {
    private List<List<Integer>> result = new ArrayList<>();

    public List<List<Integer>> permute(int[] nums) {
        backtrack(nums, 0);
        return result;
    }

    private void backtrack(int[] nums, int k) {
        if (k == nums.length) {
            List<Integer> perm = new ArrayList<>(nums.length);
            for (int v : nums) perm.add(v);
            result.add(perm);
            return;
        }
        for (int i = k; i < nums.length; i++) {
            swap(nums, k, i);      // 把候选换到第 k 位
            backtrack(nums, k + 1);
            swap(nums, k, i);      // 撤销
        }
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i]; a[i] = a[j]; a[j] = t;
    }
}
